CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK (length(display_name)<=100), avatar_url text NOT NULL DEFAULT '');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile read" ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY "Own profile update" ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO anon,authenticated,service_role;
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'name',''),100)); RETURN NEW; END; $$;
CREATE TRIGGER create_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.news_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), author_id uuid NOT NULL REFERENCES public.profiles(id), title_en text NOT NULL CHECK(length(title_en) BETWEEN 1 AND 200), title_sw text NOT NULL CHECK(length(title_sw) BETWEEN 1 AND 200), body_en text NOT NULL CHECK(length(body_en) BETWEEN 1 AND 20000), body_sw text NOT NULL CHECK(length(body_sw) BETWEEN 1 AND 20000), image_path text, video_path text, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.news_posts TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.news_posts TO authenticated; GRANT ALL ON public.news_posts TO service_role;
ALTER TABLE public.news_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published news" ON public.news_posts FOR SELECT TO anon,authenticated USING(published);
CREATE POLICY "Admin news read" ON public.news_posts FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin news insert" ON public.news_posts FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND author_id=auth.uid());
CREATE POLICY "Admin news update" ON public.news_posts FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin news delete" ON public.news_posts FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin media insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='news-media' AND public.has_role(auth.uid(),'admin') AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Admin media read" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='news-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Published media read" ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='news-media' AND EXISTS(SELECT 1 FROM public.news_posts WHERE published AND (image_path=name OR video_path=name)));
CREATE POLICY "Admin media delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='news-media' AND public.has_role(auth.uid(),'admin'));
CREATE INDEX news_published_created ON public.news_posts(published,created_at DESC);